import { useCallback, useState } from 'react';

import { Breadcrumbs, InputSearch, PageHeader } from 'components';
import { SegmentedControl } from 'components/UI';
import {
  StyledGridContainer,
  StyledHomeHeaderContainer,
} from 'shared/Styles/layout.styles';

import { SearchResults } from '../../components';
import { PILLARS_VIEW, TRAININGS_VIEW } from '../../constants';
import { ViewTypes } from '../../domain';
import { useFilterTraining, useTrainingData } from '../../hooks';
import { PillarView, TrainingView } from '../../Views';
import {
  StyledToolsContainer,
  StyledTrainingHubHome,
  StyledTrainingHubWrapper,
} from './Home.styles';

export const TrainingHubHome = () => {
  const [activeView, setActiveView] = useState<ViewTypes>(TRAININGS_VIEW);
  const [searchValue, setSearchValue] = useState<string>('');

  const { trainingData } = useTrainingData();
  const { filteredData } = useFilterTraining(searchValue);

  const handleChangeSearchValue = useCallback((value: string) => {
    setSearchValue(value);
  }, []);

  const renderActiveView = useCallback(() => {
    if (searchValue.length > 0) {
      return <SearchResults trainings={filteredData} />;
    }

    switch (activeView) {
      case TRAININGS_VIEW:
        return <TrainingView data={trainingData} />;
      case PILLARS_VIEW:
        return <PillarView data={trainingData} />;
      default:
        return <TrainingView data={trainingData} />;
    }
  }, [activeView, searchValue, filteredData]);

  return (
    <StyledGridContainer>
      <StyledTrainingHubWrapper>
        <StyledTrainingHubHome>
          <Breadcrumbs
            pageList={[{ pageName: 'Training Hub', href: '/training-hub' }]}
            showIcon={true}
          />
          <StyledHomeHeaderContainer>
            <PageHeader
              title="Training Hub"
              subtitle="Access the learning and training materials for the One Way platform."
            />
            <StyledToolsContainer>
              <InputSearch
                value={searchValue}
                onChange={handleChangeSearchValue}
              />
              <SegmentedControl
                value={activeView}
                options={[
                  { label: TRAININGS_VIEW, value: TRAININGS_VIEW },
                  { label: PILLARS_VIEW, value: PILLARS_VIEW },
                ]}
                onValueChange={(value: string) => setActiveView(value as ViewTypes)}
              />
            </StyledToolsContainer>
          </StyledHomeHeaderContainer>
        </StyledTrainingHubHome>
        {renderActiveView()}
      </StyledTrainingHubWrapper>
    </StyledGridContainer>
  );
};
